package de.cagalj.fahrtenapp;
import android.content.*;import android.net.Uri;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
public class BackupArchive {
 public static void write(Context c,Uri dest)throws Exception {try(ZipOutputStream z=new ZipOutputStream(c.getContentResolver().openOutputStream(dest))){put(z,"data.json",new Db(c).backup().toString().getBytes("UTF-8"));JSONObject prefs=new JSONObject();for(String file:new String[]{"company","auto_backup"}){JSONObject v=new JSONObject(c.getSharedPreferences(file,0).getAll());prefs.put(file,v);}prefs.put("activity",new JSONObject(c.getSharedPreferences("MainActivity",0).getAll()));put(z,"settings.json",prefs.toString().getBytes("UTF-8"));File dir=new File(c.getFilesDir(),"project_files");File[] files=dir.listFiles();if(files!=null)for(File f:files){z.putNextEntry(new ZipEntry("files/"+f.getName()));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)z.write(b,0,n);}z.closeEntry();}}}
 static void put(ZipOutputStream z,String name,byte[] b)throws IOException{z.putNextEntry(new ZipEntry(name));z.write(b);z.closeEntry();}
 public static void restore(Context c,Uri src)throws Exception{java.util.HashMap<String,byte[]> data=new java.util.HashMap<>();try(ZipInputStream z=new ZipInputStream(c.getContentResolver().openInputStream(src))){ZipEntry e;byte[] b=new byte[8192];while((e=z.getNextEntry())!=null){if(e.isDirectory())continue;String name=e.getName();if(!name.equals("data.json")&&!name.equals("settings.json")&&!name.matches("files/[a-fA-F0-9-]{36}"))throw new IOException("Ungültiger ZIP-Eintrag");ByteArrayOutputStream out=new ByteArrayOutputStream();int n;while((n=z.read(b))!=-1){out.write(b,0,n);if(out.size()>50*1024*1024)throw new IOException("Datei zu groß");}data.put(name,out.toByteArray());}}if(!data.containsKey("data.json")||!data.containsKey("settings.json"))throw new IOException("Unvollständiges Backup");JSONArray records=new JSONArray(new String(data.get("data.json"),"UTF-8"));JSONObject settings=new JSONObject(new String(data.get("settings.json"),"UTF-8"));File dir=new File(c.getFilesDir(),"project_files");dir.mkdirs();for(String key:data.keySet())if(key.startsWith("files/")){try(FileOutputStream out=new FileOutputStream(new File(dir,key.substring(6)))){out.write(data.get(key));}}new Db(c).restore(records);for(String name:new String[]{"company","auto_backup","activity"}){JSONObject prefs=settings.optJSONObject(name);if(prefs==null)continue;SharedPreferences.Editor ed=(name.equals("activity")?c.getSharedPreferences("MainActivity",0):c.getSharedPreferences(name,0)).edit();ed.clear();java.util.Iterator<String> it=prefs.keys();while(it.hasNext()){String k=it.next();Object v=prefs.get(k);if(v instanceof Boolean)ed.putBoolean(k,(Boolean)v);else if(v instanceof Integer)ed.putInt(k,(Integer)v);else if(v instanceof Long)ed.putLong(k,(Long)v);else if(v instanceof Number)ed.putFloat(k,((Number)v).floatValue());else ed.putString(k,String.valueOf(v));}ed.apply();}}
}
